#!/usr/bin/env node
/**
 * skill-security-review - static scanner for Agent Skills.
 *
 * Reads the files of a skill (or a repo of skills) and reports patterns that
 * matter for safety: network egress, process execution, secret/credential
 * access, dynamic code, filesystem writes, obfuscation, install-time scripts,
 * shipped agent transcripts, and prompt-injection style instructions inside
 * SKILL.md.
 *
 * IT NEVER EXECUTES THE TARGET. It only reads files. The scanner locates
 * things worth a human's eyes and tiers them by how they run
 * (auto-run > on-invocation > on-demand > static-text). The reviewer still
 * reads the flagged files by hand before giving a verdict.
 *
 * Usage:
 *   node scan.mjs <path-to-skill-or-repo> [--json] [--fail-on <high|medium|low>]
 *
 * Exit code is 0 unless the path is unreadable (2) or --fail-on is given and a
 * finding reaches that severity (1). Zero runtime dependencies (Node stdlib).
 */

import {
  readdirSync, readFileSync, statSync, lstatSync, realpathSync,
  openSync, readSync, closeSync,
} from 'node:fs';
import { join, relative, basename, extname, sep } from 'node:path';
import { StringDecoder } from 'node:string_decoder';

const CODE_EXTS = new Set([
  '.mjs', '.js', '.cjs', '.ts', '.tsx', '.jsx', '.py', '.sh', '.bash', '.zsh',
  '.fish', '.rb', '.pl', '.php', '.ps1', '.bat', '.cmd', '.applescript', '.scpt',
  '.lua', '.swift', '.go', '.rs',
]);
const MD_EXTS = new Set(['.md', '.markdown', '.mdx']);
const CONFIG_EXTS = new Set(['.json', '.yaml', '.yml', '.toml']);
const TRACE_EXTS = new Set(['.jsonl', '.ndjson']);
const SKIP_DIRS = new Set(['.git', 'node_modules', '.venv', 'venv', '__pycache__', 'dist', 'build', '.next', 'coverage']);
const MAX_FILE_BYTES = 2_000_000; // do not read anything larger; note it instead
const LONG_LINE = 4_000;          // past this, only the rules that stay meaningful run
const MAX_TRACE_BYTES = 512_000_000; // transcripts are streamed, so the cap can be generous

// npm lifecycle scripts that run without anyone asking, at install time.
const INSTALL_HOOKS = ['preinstall', 'install', 'postinstall', 'prepare', 'prepublish', 'prepublishOnly'];

// Every event that can wire a handler to fire on its own.
const HOOK_EVENTS = /\b(PreToolUse|PostToolUse|UserPromptSubmit|SessionStart|SessionEnd|Notification|Stop|SubagentStop|PreCompact)\b/;

// ---------------------------------------------------------------------------
// Rule catalog. Each rule: { id, category, severity, re, guard?, note? }
// severity: high | medium | low | info. guard(line, m) -> false to drop a match.
// ---------------------------------------------------------------------------

const CODE_RULES = [
  // --- network egress ---
  { id: 'net-fetch', category: 'network-egress', severity: 'medium',
    re: /\bfetch\s*\(/, note: 'HTTP request. Check the destination host and payload.' },
  { id: 'net-http-import', category: 'network-egress', severity: 'medium',
    re: /\b(require\(['"]|from ['"]|import .*['"])(node:)?(https?|net|dgram|tls|dns)\b/,
    note: 'Imports a network module.' },
  { id: 'net-ws', category: 'network-egress', severity: 'medium',
    re: /new WebSocket|WebSocketServer|socket\.io|\.connect\s*\(/,
    note: 'Opens a socket/websocket connection.' },
  { id: 'net-xhr', category: 'network-egress', severity: 'medium',
    re: /XMLHttpRequest|axios|got\(|node-fetch|urllib|requests\.(get|post|put|patch|delete)|http\.client|urlopen/,
    note: 'HTTP client usage.' },
  { id: 'net-curl', category: 'network-egress', severity: 'high',
    re: /\b(curl|wget)\b/, note: 'Shells out to curl/wget. Check URL and whether output is executed.' },
  { id: 'net-url', category: 'network-egress', severity: 'info',
    re: /https?:\/\/[a-z0-9.-]+/i,
    note: 'External URL literal (informational; correlate with fetch/exec).' },

  // --- process execution ---
  { id: 'exec-child_process', category: 'process-exec', severity: 'high',
    re: /child_process|node:child_process/, note: 'Node process execution module.' },
  { id: 'exec-call', category: 'process-exec', severity: 'high',
    re: /(^|[^.\w])(execSync|execFileSync|spawnSync|execFile|spawn|exec)\s*\(/,
    guard: (line) => !/\.\s*exec\s*\(/.test(line) && !/\bRegExp\b/.test(line),
    note: 'Runs a subprocess. NOTE: bare .exec( on a variable is usually a regex - verify.' },
  { id: 'exec-py', category: 'process-exec', severity: 'high',
    re: /\b(subprocess\.|os\.system|os\.popen|os\.exec|commands\.getoutput|pty\.spawn)/,
    note: 'Python subprocess execution.' },
  { id: 'exec-backtick', category: 'process-exec', severity: 'medium',
    re: /`[^`]*\$\([^`]*`|\bsystem\s*\(|\bexec\b.*\$/,
    note: 'Possible shell command substitution.' },

  // --- secret / credential access ---
  { id: 'secret-ssh', category: 'secret-access', severity: 'high',
    re: /\.ssh\b|id_ed25519|id_rsa|id_ecdsa|authorized_keys|known_hosts/,
    note: 'Touches SSH key material.' },
  { id: 'secret-cloud', category: 'secret-access', severity: 'high',
    re: /\.aws\/|\.config\/gcloud|\.kube\/config|\.docker\/config|\.netrc|\.npmrc|\.pypirc/,
    note: 'Reads cloud/registry credential files.' },
  { id: 'secret-keychain', category: 'secret-access', severity: 'high',
    re: /security find-generic-password|libsecret|keychain|credential.?manager|keytar/i,
    note: 'Accesses the OS credential store.' },
  { id: 'secret-agent-config', category: 'secret-access', severity: 'high',
    re: /\.claude\/(settings|\.credentials)|\.claude\.json|\.config\/(claude|anthropic)\b/,
    note: 'Touches the agent\'s own config or credential store.' },
  { id: 'secret-provider-key', category: 'secret-access', severity: 'medium',
    re: /\b(ANTHROPIC|OPENAI|GEMINI|GOOGLE|AZURE)_API_KEY\b/,
    note: 'Names a provider API key. Often just help text - check whether the value is read and then sent somewhere.' },
  { id: 'secret-env-file', category: 'secret-access', severity: 'medium',
    re: /readFileSync\([^)]*\.env|open\([^)]*\.env|dotenv|['"][^'"]*\/\.env['"]/,
    note: 'Reads a .env secrets file.' },
  { id: 'secret-env-enum', category: 'secret-access', severity: 'low',
    re: /Object\.(keys|entries|values)\s*\(\s*process\.env|for .* in os\.environ|process\.env\s*\}|JSON\.stringify\(\s*process\.env/,
    note: 'Enumerates the whole environment (possible harvest).' },
  { id: 'secret-token', category: 'secret-access', severity: 'low',
    re: /\b(api[_-]?key|secret[_-]?key|access[_-]?token|bearer|password)\b/i,
    note: 'Credential-related identifier (often benign; check if sent anywhere).' },

  // --- dynamic code ---
  { id: 'dyn-eval', category: 'dynamic-code', severity: 'high',
    re: /(^|[^.\w])eval\s*\(|new Function\s*\(|\bvm\.(runIn|compile)|\bexec\s*\(\s*compile/,
    note: 'Runs code built at runtime.' },
  { id: 'dyn-pickle', category: 'dynamic-code', severity: 'high',
    re: /pickle\.loads|marshal\.loads|yaml\.load\s*\(/,
    note: 'Deserializes into executable objects (pickle/unsafe yaml).' },
  { id: 'dyn-decode-exec', category: 'dynamic-code', severity: 'high',
    re: /(atob|Buffer\.from\([^)]*base64|b64decode|fromCharCode)[^;]{0,60}(eval|Function|exec|spawn)/,
    note: 'Decodes then executes - classic obfuscated payload.' },

  // --- filesystem ---
  { id: 'fs-destructive', category: 'filesystem', severity: 'high',
    re: /rm\s+-rf|rmdir\s+\/s|fs\.rm\s*\(|shutil\.rmtree|unlinkSync|os\.remove/,
    note: 'Deletes files/dirs.' },
  { id: 'fs-abs-write', category: 'filesystem', severity: 'medium',
    re: /writeFileSync\s*\(\s*['"]\/(?!tmp)|open\s*\(\s*['"]\/(?!tmp)[^'"]*['"]\s*,\s*['"][wa]|>>?\s*\/(etc|usr|bin|root|home)/,
    note: 'Writes to an absolute system path outside the project.' },
  { id: 'fs-agent-config-write', category: 'filesystem', severity: 'high',
    re: /(writeFileSync|appendFileSync|open|>>?)[^\n]{0,60}(\.claude\/settings|\.claude\.json|CLAUDE\.md|\.claude\/skills|\.mcp\.json)/,
    note: 'Writes to the agent\'s own config/skills - persistence and self-modification.' },
  { id: 'fs-home', category: 'filesystem', severity: 'low',
    re: /os\.homedir\s*\(\)|expanduser\(|process\.env\.HOME|\$HOME/,
    note: 'Resolves the home directory (check what it does there).' },

  // --- obfuscation ---
  { id: 'obf-base64', category: 'obfuscation', severity: 'medium',
    re: /['"][A-Za-z0-9+/]{120,}={0,2}['"]/,
    note: 'Long base64/opaque literal.' },
  { id: 'obf-hex', category: 'obfuscation', severity: 'low',
    re: /(\\x[0-9a-f]{2}){10,}/i, note: 'Long hex-escaped string.' },
];

// Zero-width / bidi control characters (used to hide instructions in text).
// Written as escapes on purpose: the literal characters must not appear in this file.
const HIDDEN_CHARS = /[​-‏‪-‮⁠-⁤﻿]/;

const MD_RULES = [
  { id: 'md-pipe-shell', category: 'injection', severity: 'high',
    re: /\b(curl|wget)\b[^\n|]*\|\s*(sudo\s+)?(sh|bash|zsh|python|node)\b/i,
    note: 'Instructs piping a download straight into an interpreter.' },
  { id: 'md-run-remote', category: 'injection', severity: 'high',
    re: /\b(npm\s+i(nstall)?|pip\s+install|npx|uvx|gem\s+install|go\s+install)\b[^\n]*(https?:\/\/|git\+|github\.com\/[^\s)]+)/i,
    note: 'Instructs installing/executing code from a remote/arbitrary source.' },
  { id: 'md-override', category: 'injection', severity: 'high',
    re: /ignore (all |the |any )?(previous|prior|earlier|above) (instructions|prompts|rules)|disregard (the )?(system|previous)|override.{0,20}(system|safety)/i,
    note: 'Prompt-injection: tries to override the agent\'s own instructions.' },
  { id: 'md-hide-from-user', category: 'injection', severity: 'high',
    re: /(do not|don't|never) (tell|inform|mention|show|reveal).{0,30}(user|human)|without (telling|informing|asking) the user/i,
    note: 'Tells the agent to act behind the user\'s back.' },
  { id: 'md-exfil', category: 'injection', severity: 'high',
    re: /\b(send|post|upload|exfiltrat|transmit|report|beacon)\b[^\n]{0,50}\b(env|environment|token|key|secret|credential|\.ssh|password|contents|history)\b/i,
    note: 'Instructs sending local/secret data somewhere.' },
  { id: 'md-read-secrets', category: 'injection', severity: 'high',
    re: /\b(read|cat|open|load|collect|gather)\b[^\n]{0,40}(\.ssh|\.env|id_rsa|id_ed25519|\.aws|credentials|\.netrc|password|api[_-]?key)\b/i,
    note: 'Instructs reading credential/secret files.' },
  { id: 'md-bypass-guardrail', category: 'injection', severity: 'high',
    re: /auto[- ]approve|bypass.{0,20}(permission|confirmation|sandbox|guardrail)|skip.{0,15}(permission|confirmation|approval) (check|prompt|dialog)|--dangerously|already (been )?(approved|authorized|authorised)/i,
    note: 'Claims an action needs no approval, or names a guardrail to switch off.' },
  { id: 'md-skip-review', category: 'injection', severity: 'medium',
    re: /\b(do not|don't|never|no need to) (ask|confirm|prompt|check with|verify with)[^\n]{0,30}(user|permission|approval)/i,
    note: 'Tells the agent not to ask the user. Often benign workflow prose ("do not ask them to install X") - read the sentence and decide.' },
  { id: 'md-run-script', category: 'process-exec', severity: 'low',
    re: /(you MUST|always|first)[^\n]{0,40}\b(run|execute)\b[^\n]{0,40}\b(node|python|bash|sh|\.mjs|\.py|\.sh|scripts\/)/i,
    note: 'Setup step that runs a bundled script (read that script).' },
];

// --- agent transcripts and opaque reasoning blocks -------------------------
// Providers return chain-of-thought as an encrypted block the client stores and
// replays. Such a block is opaque to the person publishing it: it can carry the
// author's own secrets, and it can steer whatever agent replays it, with nothing
// visible in the plaintext. See arXiv:2608.09867.

const TRACE_RULES = [
  { id: 'trace-signature-blob', category: 'agent-trace', severity: 'high',
    re: /"(signature|thinking_signature|thinkingSignature|thought_signature|thoughtSignature|encrypted_content)"\s*:\s*"[A-Za-z0-9+/=_-]{100,}"/,
    note: 'Encrypted reasoning block shipped with the skill. Opaque to reviewers: it can steer any agent that replays it and may contain the author\'s own leaked secrets.' },
  { id: 'trace-field', category: 'agent-trace', severity: 'medium',
    re: /\b(thinkingSignature|thinking_signature|thoughtSignature|thought_signature|redacted_thinking|encrypted_content|reasoning_encrypted)\b/,
    note: 'Field that carries an opaque model reasoning block. Check whether a real block ships with the skill.' },
  { id: 'trace-block', category: 'agent-trace', severity: 'low',
    re: /"type"\s*:\s*"(thinking|reasoning|thought|thought_signature)"|"reasoning_content"\s*:|"reasoning"\s*:\s*\{/,
    note: 'Looks like a captured model reasoning block inside a transcript.' },
];

// Only the unambiguous blob rule runs against prose - the field names appear in
// legitimate documentation (this skill's own reference pages, for one).
const TRACE_RULES_TEXT = TRACE_RULES.filter(r => r.id === 'trace-signature-blob');

// Credential rules, reused on transcripts where the rest of CODE_RULES is noise.
const SECRET_RULES = CODE_RULES.filter(r => r.category === 'secret-access');

const TRANSCRIPT_NAME = /(^|[/-])(transcript|session|trace|rollout|conversation|history|messages)[\w.-]*\.(jsonl|ndjson|json)$/i;

// ---------------------------------------------------------------------------
// File walk + classification
// ---------------------------------------------------------------------------

function safeRealpath(p) {
  try { return realpathSync(p); } catch { return null; }
}

function insideRoot(realPath, root) {
  return realPath === root || realPath.startsWith(root + sep);
}

/**
 * Walk the tree. Symlinks are resolved explicitly: a link that stays inside the
 * skill is followed (and noted), a link that escapes the tree is reported and
 * never read. Directory realpaths are remembered so a link loop cannot recurse
 * forever, and a file reached twice is scanned once.
 */
function walk(dir, root, ctx) {
  let entries;
  try { entries = readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const e of entries) {
    const full = join(dir, e.name);
    if (e.isSymbolicLink()) { followSymlink(full, root, ctx); continue; }
    if (e.isDirectory()) {
      if (SKIP_DIRS.has(e.name)) continue;
      descend(full, root, ctx);
    } else if (e.isFile()) {
      addFile(full, root, ctx);
    }
  }
}

function descend(dir, root, ctx) {
  const rp = safeRealpath(dir);
  if (!rp) return;
  if (ctx.visitedDirs.has(rp)) return;
  ctx.visitedDirs.add(rp);
  walk(dir, root, ctx);
}

function addFile(file, root, ctx) {
  const rp = safeRealpath(file) || file;
  if (ctx.seenFiles.has(rp)) return;
  ctx.seenFiles.add(rp);
  ctx.files.push(file);
}

function followSymlink(link, root, ctx) {
  const rel = relative(root, link) || basename(link);
  const rp = safeRealpath(link);
  if (!rp) {
    ctx.linkFindings.push({
      file: rel, line: 1, rule: 'link-broken', category: 'symlink', severity: 'info',
      snippet: `${rel} -> (unresolvable)`,
      note: 'Broken symlink. Nothing to read, but note why the skill ships it.',
    });
    return;
  }
  if (!insideRoot(rp, root)) {
    ctx.linkFindings.push({
      file: rel, line: 1, rule: 'link-escapes-tree', category: 'symlink', severity: 'high',
      snippet: `${rel} -> ${rp}`,
      note: 'Symlink points outside the skill directory. Not read by this scanner. A link into $HOME, ~/.ssh or the agent config is an exfiltration path the moment anything copies or reads it.',
    });
    return;
  }
  let st;
  try { st = statSync(rp); } catch { return; }
  ctx.linkFindings.push({
    file: rel, line: 1, rule: 'link-internal', category: 'symlink', severity: 'info',
    snippet: `${rel} -> ${relative(root, rp) || '.'}`,
    note: 'Content reached through a symlink inside the skill. Followed and scanned; make sure the report path matches what you read.',
  });
  if (st.isDirectory()) descend(link, root, ctx);
  else if (st.isFile()) addFile(link, root, ctx);
}

/**
 * Yield a file's lines without holding it in memory. Recorded sessions run to
 * tens of megabytes - far over the read limit that protects the rest of the
 * scan - and they are exactly the files the trace rules exist for, so they get
 * streamed instead of skipped.
 */
function* readLines(file, maxBytes = MAX_TRACE_BYTES) {
  let fd;
  try { fd = openSync(file, 'r'); } catch { return; }
  const decoder = new StringDecoder('utf-8');
  const buf = Buffer.alloc(1 << 20);
  let carry = '';
  let total = 0;
  try {
    for (;;) {
      let read = 0;
      try { read = readSync(fd, buf, 0, buf.length, null); } catch { break; }
      if (read <= 0) break;
      total += read;
      const parts = (carry + decoder.write(buf.subarray(0, read))).split('\n');
      carry = parts.pop();
      for (const p of parts) yield p;
      if (total >= maxBytes) break;
    }
    carry += decoder.end();
    if (carry) yield carry;
  } finally {
    try { closeSync(fd); } catch { /* ignore */ }
  }
}

function headBytes(file, n = 512) {
  let fd;
  try {
    fd = openSync(file, 'r');
    const buf = Buffer.alloc(n);
    const read = readSync(fd, buf, 0, n, 0);
    return buf.subarray(0, read);
  } catch {
    return Buffer.alloc(0);
  } finally {
    if (fd !== undefined) { try { closeSync(fd); } catch { /* ignore */ } }
  }
}

function isExecutable(file) {
  try { return (lstatSync(file).mode & 0o111) !== 0; } catch { return false; }
}

/**
 * Classify by extension, then - for anything unrecognised - by content. A
 * shebang makes a file code whatever it is called; a NUL byte makes it binary.
 * Skipping extensionless scripts was a full bypass of every rule below.
 */
function classify(file) {
  const ext = extname(file).toLowerCase();
  const name = basename(file).toLowerCase();
  if (MD_EXTS.has(ext)) return 'markdown';
  if (TRACE_EXTS.has(ext)) return 'trace';
  if (CONFIG_EXTS.has(ext)) return 'config';
  if (CODE_EXTS.has(ext)) {
    if (/\.(min|umd|bundle)\.js$/.test(name)) return 'vendored';
    return 'code';
  }
  const head = headBytes(file);
  if (head.length === 0) return 'asset';
  if (head.includes(0)) return 'binary';
  if (head[0] === 0x23 && head[1] === 0x21) return 'code'; // "#!"
  return 'asset';
}

function isVendoredByContent(text) {
  // Single very long line = minified/vendored bundle. Note it, do not line-scan.
  const firstBreak = text.indexOf('\n');
  const longestLine = text.split('\n').reduce((a, l) => Math.max(a, l.length), 0);
  return longestLine > 2000 || (firstBreak === -1 && text.length > 2000);
}

// ---------------------------------------------------------------------------
// Pattern-definition detection (noise control)
//
// A security tool, a linter, or any code that hunts for a string necessarily
// contains that string. Matching inside a regex literal is a syntactic fact, so
// the finding is downgraded to info and kept, never dropped.
// ---------------------------------------------------------------------------

function regexLiteralSpans(line) {
  const spans = [];
  let i = 0;
  while (i < line.length) {
    if (line[i] === '/') {
      const before = line.slice(0, i).trimEnd();
      const prev = before.slice(-1);
      const opensRegex = prev === '' || '=(,:[!&|?{;+*%^~'.includes(prev);
      if (opensRegex && line[i + 1] !== '/' && line[i + 1] !== '*') {
        let j = i + 1, close = -1, inClass = false;
        while (j < line.length) {
          const c = line[j];
          if (c === '\\') { j += 2; continue; }
          if (c === '[') inClass = true;
          else if (c === ']') inClass = false;
          else if (c === '/' && !inClass) { close = j; break; }
          j++;
        }
        if (close > i) { spans.push([i, close]); i = close + 1; continue; }
      }
    }
    i++;
  }
  return spans;
}

const PATTERN_PROP = /(^|[\s{,])(re|regex|pattern|rule|match|detect|signature)s?\s*:/i;
// Keys whose value is prose meant for a human, not a command.
const PROSE_KEY = /\b(note|description|desc|message|msg|help|hint|summary|title|label|text)\s*:\s*$/i;
// A line carrying several of these reads as a catalog entry, not as logic.
const CATALOG_KEY = /\b(id|rule|category|severity|tier|name|note|pattern|re)\s*:/g;

/** Spans of quoted string literals on a line: [start, end, quoteChar]. */
function stringSpans(line) {
  const spans = [];
  let i = 0;
  while (i < line.length) {
    const ch = line[i];
    if (ch === '"' || ch === "'" || ch === '`') {
      let j = i + 1;
      while (j < line.length) {
        if (line[j] === '\\') { j += 2; continue; }
        if (line[j] === ch) break;
        j++;
      }
      if (j < line.length) { spans.push([i, j, ch]); i = j + 1; continue; }
    }
    i++;
  }
  return spans;
}

function enclosingString(line, index) {
  for (const span of stringSpans(line)) {
    if (index >= span[0] && index <= span[1]) return span;
  }
  return null;
}

/**
 * True when the match is a pattern being *described* rather than code that runs:
 * inside a regex literal, inside a rule-catalog entry, or inside a prose field.
 * A detector necessarily contains every string it hunts for.
 */
function isPatternDefinition(line, index) {
  for (const [a, b] of regexLiteralSpans(line)) {
    if (index >= a && index <= b) return true;
  }
  if (PATTERN_PROP.test(line) && /['"/]/.test(line)) return true;
  if (/re\.compile\s*\(|new RegExp\s*\(/.test(line)) return true;
  const span = enclosingString(line, index);
  if (span) {
    const before = line.slice(0, span[0]);
    if (PROSE_KEY.test(before)) return true;
    const keys = line.match(CATALOG_KEY);
    if (keys && keys.length >= 2) return true;
  }
  return false;
}

/**
 * In prose, an attack string cited inside backticks or quotation marks is an
 * example. Documentation about injection is not injection.
 */
function isQuotedInProse(line, index) {
  for (const [a, b, q] of stringSpans(line)) {
    if ((q === '`' || q === '"') && index >= a && index <= b) return true;
  }
  return false;
}

// ---------------------------------------------------------------------------
// Entry-point (tier) detection
// ---------------------------------------------------------------------------

function resolveRef(ref, files, root) {
  const clean = ref.replace(/^\.?\/?/, '');
  return files.find(x => x.endsWith(sep + clean) || x.endsWith('/' + clean) || relative(root, x) === clean)
      || files.find(x => basename(x) === basename(clean));
}

function detectAutoRun(files, root, texts) {
  const autorun = new Set();
  for (const f of files) {
    const rel = relative(root, f);
    if (/(^|\/)hook[\w.-]*\.(mjs|cjs|js|py|sh|bash)$/i.test(rel)) autorun.add(f);
    if (/(^|\/)(pre|post)[-_]?tool[-_]?use/i.test(rel)) autorun.add(f);
    if (/(^|\/)hooks?\//i.test(rel) && classify(f) === 'code') autorun.add(f);
  }
  for (const f of files) {
    const rel = relative(root, f);
    if (!/hooks?\.json$|settings(\.local)?\.json$|\.claude-plugin\/|\.mcp\.json$|plugin\.json$/i.test(rel)) continue;
    const t = texts.get(f) || '';
    for (const m of t.matchAll(/["']([^"']*\.(?:mjs|cjs|js|py|sh|bash))["']/g)) {
      const cand = resolveRef(m[1], files, root);
      if (cand) autorun.add(cand);
    }
    if (HOOK_EVENTS.test(t) || /"hooks"/.test(t) || /"mcpServers"/.test(t)) autorun.add(f);
  }
  return autorun;
}

function detectOnInvocation(skillMd, files, root) {
  const oninv = new Set();
  if (!skillMd) return oninv;
  for (const m of skillMd.text.matchAll(/(?:node|python3?|bash|sh|\.\/)\s+([\w./-]+\.(?:mjs|cjs|js|py|sh|bash))/g)) {
    const cand = resolveRef(m[1], files, root);
    if (cand) oninv.add(cand);
  }
  return oninv;
}

function tierFor(file, autorun, oninv, kind) {
  if (autorun.has(file)) return 'auto-run';
  if (oninv.has(file)) return 'on-invocation';
  if (kind === 'markdown') return 'static-text';
  return 'on-demand';
}

// ---------------------------------------------------------------------------
// Manifest-level checks: install scripts, MCP servers, declared tools
// ---------------------------------------------------------------------------

function lineOf(text, needle) {
  const idx = text.indexOf(needle);
  if (idx < 0) return 1;
  return text.slice(0, idx).split('\n').length;
}

function detectInstallScripts(files, root, texts, autorun) {
  const out = [];
  for (const f of files) {
    if (basename(f) !== 'package.json') continue;
    const text = texts.get(f) || '';
    let pkg;
    try { pkg = JSON.parse(text); } catch { continue; }
    const scripts = pkg && typeof pkg.scripts === 'object' ? pkg.scripts : {};
    for (const hook of INSTALL_HOOKS) {
      if (!scripts[hook]) continue;
      autorun.add(f);
      out.push({
        file: relative(root, f) || basename(f), line: lineOf(text, `"${hook}"`),
        rule: 'install-script', category: 'install-time', severity: 'high', tier: 'auto-run',
        snippet: `"${hook}": ${JSON.stringify(scripts[hook]).slice(0, 160)}`,
        note: `npm "${hook}" runs automatically when the package is installed - before anyone reviews anything. Read the command it runs.`,
      });
    }
  }
  return out;
}

function detectMcpServers(files, root, texts) {
  const out = [];
  for (const f of files) {
    // Config files only: a scanner's own source mentions the key without wiring one.
    if (!CONFIG_EXTS.has(extname(f).toLowerCase())) continue;
    const text = texts.get(f) || '';
    if (!/"mcpServers"/.test(text)) continue;
    let cfg;
    try { cfg = JSON.parse(text); } catch { cfg = null; }
    const servers = cfg && cfg.mcpServers ? Object.entries(cfg.mcpServers) : [];
    const detail = servers.length
      ? servers.map(([n, s]) => `${n}: ${[s && s.command, ...(s && Array.isArray(s.args) ? s.args : [])].filter(Boolean).join(' ')}`).join(' | ')
      : '(unparsed)';
    out.push({
      file: relative(root, f) || basename(f), line: lineOf(text, '"mcpServers"'),
      rule: 'mcp-server', category: 'mcp-server', severity: 'high', tier: 'auto-run',
      snippet: detail.slice(0, 200),
      note: 'Declares an MCP server. Its command starts with the session and its tool descriptions enter the agent context - a second install surface with its own code and its own injection surface.',
    });
  }
  return out;
}

function parseFrontmatter(text) {
  if (!text.startsWith('---')) return null;
  const end = text.indexOf('\n---', 3);
  if (end < 0) return null;
  const raw = text.slice(text.indexOf('\n') + 1, end);
  // Plain line walk on purpose: no dynamic RegExp built from strings.
  const get = (key) => {
    for (const line of raw.split('\n')) {
      const colon = line.indexOf(':');
      if (colon < 0) continue;
      if (line.slice(0, colon).trim().toLowerCase() !== key) continue;
      const value = line.slice(colon + 1).trim();
      return value || null;
    }
    return null;
  };
  return { raw, endLine: raw.split('\n').length + 2, allowedTools: get('allowed-tools'), description: get('description'), name: get('name') };
}

// ---------------------------------------------------------------------------
// Scan
// ---------------------------------------------------------------------------

function scanFileLines(lines, rules, rel, kind, frontmatterEndLine) {
  const findings = [];
  const urls = new Set();
  let urlLine = 0;
  const isCode = kind === 'code' || kind === 'config' || kind === 'trace';
  let i = -1;
  for (const line of lines) {
    i++;
    let active = rules;
    if (line.length > LONG_LINE) {
      // A recorded session is one JSON object per line and a single reasoning
      // block runs to tens of thousands of characters, so skipping long lines
      // outright hid the very blocks this scanner exists to find. Run the rules
      // that survive on one enormous line; the rest would only be noise.
      active = rules.filter(r => r.category === 'agent-trace' || r.category === 'secret-access');
      if (!active.length) continue;
    }
    const trimmed = line.length > LONG_LINE ? line.slice(0, 400).trim() : line.trim();
    // Commented-out code does not run. Line 1 is exempt: it may be a shebang.
    const isCommentLine = isCode && (/^(\/\/|\*|\/\*)/.test(trimmed) || (i > 0 && /^#(?!!)/.test(trimmed)));
    if (!isCommentLine) {
      for (const rule of active) {
        const m = rule.re.exec(line);
        if (!m) continue;
        if (rule.guard && !rule.guard(line, m)) continue;
        if (rule.id === 'net-url') {
          for (const u of line.matchAll(/https?:\/\/([a-z0-9.-]+)/gi)) urls.add(u[1].toLowerCase());
          if (!urlLine) urlLine = i + 1;
          continue;
        }
        let severity = rule.severity;
        let note = rule.note;
        if (rule.category === 'network-egress' && /\b(localhost|127\.0\.0\.1|0\.0\.0\.0|::1)\b/.test(line)) {
          severity = severity === 'high' ? 'low' : 'info';
        }
        if (isCode && isPatternDefinition(line, m.index)) {
          severity = 'info';
          note = `${note} [match sits inside a pattern/regex definition or a prose field, not a call - a detector contains the strings it hunts for]`;
        } else if (kind === 'markdown' && isQuotedInProse(line, m.index)) {
          severity = severity === 'high' ? 'low' : 'info';
          note = `${note} [quoted as an example in prose, not addressed to the agent - confirm by reading the sentence around it]`;
        }
        const f = {
          file: rel, line: i + 1, rule: rule.id, category: rule.category,
          severity, snippet: trimmed.slice(0, 200), note,
        };
        if (frontmatterEndLine && i + 1 <= frontmatterEndLine) {
          f.frontmatter = true;
          f.note = `${note} [in the frontmatter, which is loaded into the agent context whether or not the skill is invoked]`;
        }
        findings.push(f);
      }
    }
    if (HIDDEN_CHARS.test(line)) {
      const idx = line.search(HIDDEN_CHARS);
      const inPattern = isCode && isPatternDefinition(line, idx);
      findings.push({
        file: rel, line: i + 1, rule: 'hidden-unicode', category: 'obfuscation',
        severity: inPattern ? 'info' : 'high',
        snippet: '[zero-width / bidi control characters present]',
        note: inPattern
          ? 'Invisible characters inside a pattern definition (a detector for them). Confirm that is all it is.'
          : 'Invisible characters can hide instructions or code. Inspect with a hex view.',
      });
    }
  }
  if (urls.size) {
    const list = [...urls].sort();
    findings.push({
      file: rel, line: urlLine || 1, rule: 'net-url', category: 'network-egress', severity: 'info',
      snippet: `${list.length} external host(s): ${list.slice(0, 12).join(', ')}${list.length > 12 ? ', ...' : ''}`,
      note: 'External URL literals, aggregated per file. Only meaningful next to a fetch/exec - documentation links are not egress.',
    });
  }
  return findings;
}

function main() {
  const args = process.argv.slice(2);
  const asJson = args.includes('--json');
  const failIdx = args.findIndex(a => a === '--fail-on' || a.startsWith('--fail-on='));
  let failOn = null;
  if (failIdx >= 0) {
    const a = args[failIdx];
    failOn = a.includes('=') ? a.split('=')[1] : args[failIdx + 1];
  }
  const target = args.find((a, i) => !a.startsWith('--') && !(failIdx >= 0 && i === failIdx + 1 && !args[failIdx].includes('=')));
  if (!target) {
    console.error('usage: node scan.mjs <path-to-skill-or-repo> [--json] [--fail-on <high|medium|low>]');
    process.exit(2);
  }
  let st;
  try { st = statSync(target); } catch (e) { console.error(`cannot read ${target}: ${e.message}`); process.exit(2); }

  // Resolve the root first: installed skills are very often symlinks themselves.
  const rootReal = safeRealpath(st.isDirectory() ? target : join(target, '..'));
  const root = rootReal || (st.isDirectory() ? target : join(target, '..'));
  const ctx = { files: [], visitedDirs: new Set(), seenFiles: new Set(), linkFindings: [] };
  if (st.isDirectory()) { ctx.visitedDirs.add(root); walk(root, root, ctx); } else { addFile(target, root, ctx); }
  const files = ctx.files;

  // Read text once per file.
  const texts = new Map();
  const inventory = [];
  const inventoryByRel = new Map();
  const skillMds = [];
  const notes = [];
  const streamed = new Set();
  const extraFindings = [...ctx.linkFindings];

  for (const f of files) {
    const rel = relative(root, f) || basename(f);
    let kind = classify(f);
    let size = 0;
    try { size = statSync(f).size; } catch { /* ignore */ }
    let text = '';
    const readable = kind === 'code' || kind === 'markdown' || kind === 'config' || kind === 'trace' || kind === 'vendored';
    if (readable && size <= MAX_FILE_BYTES) {
      try { text = readFileSync(f, 'utf-8'); } catch { /* ignore */ }
      if (kind === 'code' && isVendoredByContent(text)) kind = 'vendored';
    } else if ((kind === 'trace' || TRANSCRIPT_NAME.test(rel)) && size <= MAX_TRACE_BYTES) {
      // Real transcripts run to tens of megabytes, well over the read limit
      // that protects the rest of the scan, and skipping one would silently
      // disable the very rules it exists for. Stream it instead. The name test
      // is what stops `session.json` from dodging this by not being .jsonl.
      kind = 'trace';
      streamed.add(f);
      notes.push(`Streamed line by line, too large to hold in memory: ${rel} (${size} bytes).`);
    } else if (readable) {
      notes.push(`Not scanned, over the ${MAX_FILE_BYTES} byte limit: ${rel} (${size} bytes). Read it yourself or treat it as opaque.`);
    }
    if (kind === 'binary') {
      extraFindings.push({
        file: rel, line: 1, rule: 'shipped-binary', category: 'opaque-binary',
        severity: isExecutable(f) ? 'high' : 'medium', tier: 'on-demand',
        snippet: `${rel} (${size} bytes${isExecutable(f) ? ', executable bit set' : ''})`,
        note: 'Binary shipped inside a skill. Nothing here can review it. Either it is a known asset (font, image, model) or the skill should not ship it.',
      });
    }
    if (TRANSCRIPT_NAME.test(rel) || kind === 'trace') {
      extraFindings.push({
        file: rel, line: 1, rule: 'ships-transcript', category: 'agent-trace', severity: 'medium', tier: 'on-demand',
        snippet: `${rel} (${size} bytes)`,
        note: 'Looks like a shipped agent transcript. Check it for encrypted reasoning blocks before you resume, replay, or publish it.',
      });
    }
    texts.set(f, text);
    const entry = { file: rel, kind, bytes: size };
    inventory.push(entry);
    inventoryByRel.set(rel, entry);
    if (basename(f).toLowerCase() === 'skill.md') skillMds.push({ file: f, rel, text });
  }

  const autorun = detectAutoRun(files, root, texts);
  const primarySkillMd = skillMds[0];
  const oninv = detectOnInvocation(primarySkillMd, files, root);
  const installFindings = detectInstallScripts(files, root, texts, autorun);
  const mcpFindings = detectMcpServers(files, root, texts);
  extraFindings.push(...installFindings, ...mcpFindings);

  if (files.some(f => basename(f) === '.gitmodules')) {
    notes.push('.gitmodules present: this repo pulls in submodules. `git clone` without --recurse-submodules did not fetch them, so their code was not reviewed.');
  }

  const frontmatterByFile = new Map();
  for (const s of skillMds) {
    const fm = parseFrontmatter(s.text);
    if (fm) frontmatterByFile.set(s.rel, fm);
  }

  const findings = [];
  for (const f of files) {
    const rel = relative(root, f) || basename(f);
    const kind = inventoryByRel.get(rel)?.kind;
    const text = texts.get(f) || '';
    if (kind === 'vendored') {
      notes.push(`Vendored/minified, not line-scanned: ${rel} (read the source repo or treat as opaque).`);
      continue;
    }
    let ruleset = null;
    // A transcript is a recording, not code: an agent that once ran `curl | sh`
    // in a session would otherwise flood the report with process-exec findings
    // for something that already happened and cannot run again from this file.
    // What matters in a recording is leaked secrets and opaque reasoning blocks.
    if (kind === 'trace') ruleset = [...TRACE_RULES, ...SECRET_RULES];
    else if (kind === 'code' || kind === 'config') ruleset = [...CODE_RULES, ...TRACE_RULES];
    else if (kind === 'markdown') ruleset = [...MD_RULES, ...TRACE_RULES_TEXT];
    if (!ruleset) continue;
    const lines = streamed.has(f) ? readLines(f) : (text ? text.split('\n') : null);
    if (!lines) continue;
    const fm = frontmatterByFile.get(rel);
    const fileFindings = scanFileLines(lines, ruleset, rel, kind, fm ? fm.endLine : 0);
    const tier = tierFor(f, autorun, oninv, kind);
    for (const fnd of fileFindings) { fnd.tier = tier; findings.push(fnd); }
  }
  findings.push(...extraFindings.map(f => ({ tier: 'on-demand', ...f })));

  // Summaries
  const sevOrder = { high: 0, medium: 1, low: 2, info: 3 };
  const tierOrder = { 'auto-run': 0, 'on-invocation': 1, 'on-demand': 2, 'static-text': 3 };
  findings.sort((a, b) =>
    (tierOrder[a.tier] - tierOrder[b.tier]) || (sevOrder[a.severity] - sevOrder[b.severity]) ||
    a.file.localeCompare(b.file) || a.line - b.line);

  const counts = { code: 0, markdown: 0, config: 0, trace: 0, asset: 0, vendored: 0, binary: 0 };
  for (const it of inventory) counts[it.kind] = (counts[it.kind] || 0) + 1;
  const bySev = {}; const byCat = {};
  for (const f of findings) { bySev[f.severity] = (bySev[f.severity] || 0) + 1; byCat[f.category] = (byCat[f.category] || 0) + 1; }

  const executable = [];
  if (counts.code > 0) executable.push(`${counts.code} script(s)`);
  if (counts.binary > 0) executable.push(`${counts.binary} binary/binaries`);
  if (installFindings.length) executable.push(`${installFindings.length} install-time script(s)`);
  if (mcpFindings.length) executable.push(`${mcpFindings.length} MCP server declaration(s)`);

  const fm = primarySkillMd ? frontmatterByFile.get(primarySkillMd.rel) : null;

  const result = {
    target,
    root,
    summary: {
      files: inventory.length,
      byKind: counts,
      hasCode: executable.length > 0,
      executableSurface: executable,
      declaredTools: fm ? fm.allowedTools : null,
      autoRunEntrypoints: [...autorun].map(f => relative(root, f)),
      symlinksFollowed: ctx.linkFindings.filter(f => f.rule === 'link-internal').length,
      symlinksEscaping: ctx.linkFindings.filter(f => f.rule === 'link-escapes-tree').length,
      findings: findings.length,
      bySeverity: bySev,
      byCategory: byCat,
    },
    findings,
    inventory,
    notes,
  };

  const failRank = failOn ? sevOrder[failOn] : null;
  const worst = findings.reduce((a, f) => Math.min(a, sevOrder[f.severity]), 99);
  const shouldFail = failRank !== undefined && failRank !== null && worst <= failRank;

  // process.exit() truncates a pending stdout write to a pipe, which silently
  // corrupts --json for every consumer. Set the code and let Node drain.
  if (asJson) {
    console.log(JSON.stringify(result, null, 2));
    process.exitCode = shouldFail ? 1 : 0;
    return;
  }

  // Human-readable summary
  const s = result.summary;
  const L = [];
  L.push(`# skill-security-review scan: ${target}`);
  L.push('');
  L.push(`Files: ${s.files}  (code ${counts.code}, markdown ${counts.markdown}, config ${counts.config}, trace ${counts.trace}, vendored ${counts.vendored}, binary ${counts.binary}, asset ${counts.asset})`);
  L.push(`Executable surface: ${executable.length ? executable.join(', ') : 'none (markdown-only)'}`);
  if (s.declaredTools) L.push(`Declared allowed-tools: ${s.declaredTools}`);
  L.push(`Auto-run entrypoints: ${s.autoRunEntrypoints.length ? s.autoRunEntrypoints.join(', ') : 'none detected'}`);
  if (s.symlinksFollowed || s.symlinksEscaping) {
    L.push(`Symlinks: ${s.symlinksFollowed} followed inside the tree, ${s.symlinksEscaping} pointing outside (not read)`);
  }
  L.push(`Findings: ${s.findings}  (${Object.entries(bySev).map(([k, v]) => `${k}:${v}`).join(', ') || 'none'})`);
  L.push('');
  if (notes.length) { L.push('Notes:'); for (const n of notes) L.push(`  - ${n}`); L.push(''); }
  if (!findings.length) {
    L.push('No pattern matches. Still read SKILL.md and any code by hand before trusting.');
  } else {
    let curTier = null;
    for (const f of findings) {
      if (f.tier !== curTier) { curTier = f.tier; L.push(`## tier: ${curTier}`); }
      L.push(`  [${f.severity}] ${f.category}/${f.rule}  ${f.file}:${f.line}${f.frontmatter ? '  (frontmatter)' : ''}`);
      L.push(`      ${f.snippet}`);
      if (f.note) L.push(`      -> ${f.note}`);
    }
  }
  L.push('');
  L.push('Reminder: this locates; it does not judge. Read every auto-run and flagged file by hand.');
  console.log(L.join('\n'));
  process.exitCode = shouldFail ? 1 : 0;
}

main();
